{
  "name": "audio_search",
  "title": "有声内容搜索与播放",
  "url": "http://{music-service-host}:{port}/v1/service/audio",
  "method": "POST",
  "description": "功能：基于用户语音查询在有声（听书/相声/评书/儿童故事/知识付费等音频专辑）媒资库中检索并按场景组织结果，统一承载「有声搜索」「有声播放」「有声熄屏播放」三类原始意图，通过 play_mode + screen_mode 区分下游落地行为（多结果列表展示 / 单媒资起播 / 熄屏起播）。\n适用场景：用户口播需要查找、听、播放某个有声专辑/主播/分类，或在熄屏(TVMODE=6)场景下希望直接起播有声内容。典型说法如「我想听郭德纲的相声」「播放三国演义评书」「熄屏听会儿睡前故事」。\n不适用场景：音乐/歌曲搜索请使用 music_song_search；有声直达页面（如打开有声首页/历史记录页）请使用 audio_page / audio_history；针对当前在播内容的问答请使用 audio_chat；纯设备控制（暂停/下一集）请使用设备控制智能体。\n关联工具：直达页面用 audio_page，历史记录起播用 audio_history，媒资问答用 audio_chat，不支持有声APK时会被上游转为 audio_unsupported。\n异常：终端未安装有声APK(audioversion为空)时熄屏播放会自动回退为亮屏参数(screenoper=1)；无媒资命中时走推荐兜底或空结果闲聊话术。\n结果使用：将 data.content.searchResultList 渲染为有声卡片列表；ttscontent 用于语音播报；screenoper 决定终端亮/熄屏；subsort=audio_play 时终端直接起播首条媒资，subsort=audio 时展示列表；memoryData 用于多轮记忆写入。",
  "parameters": {
    "type": "object",
    "properties": {
      "query": {
        "type": "string",
        "description": "用户语音经敏感词及归一化处理后的查询文本（对应下游 normalText 字段），如「郭德纲的相声」「三国演义评书」。"
      },
      "retext": {
        "type": "string",
        "description": "用户语音原始文本，用于日志/回复语拼接，如「我想听郭德纲的相声」。"
      },
      "play_mode": {
        "type": "string",
        "description": "播放模式，标识本次调用应承载的原始意图行为。\n- search：亮屏搜索场景，命中多条时下发有声搜索卡片列表，subsort=audio；\n- play：亮屏播放场景，命中即选首条起播，subsort=audio_play；\n- screen_off_play：熄屏播放场景，subsort=audio_play 且下发 screenoper=0。",
        "enum": ["search", "play", "screen_off_play"]
      },
      "screen_mode": {
        "type": "string",
        "description": "终端屏幕状态，取自 configMap.tvmode。\n- normal：亮屏（tvmode≠6）；\n- screen_standby：熄屏待机（tvmode=6），触发熄屏播放分支。",
        "enum": ["normal", "screen_standby"]
      },
      "word_list": {
        "type": "array",
        "description": "分词与语义标签列表，用于下游有声媒资搜索的槽位过滤（如有声书名、主播、类型、播放/听 关键词等）。每个元素为 {word, tag, ...} 的槽位对象。"
      },
      "rule_intent_flag": {
        "type": "string",
        "description": "强规则意图标识。\n- 1：中控命中强规则（如「播放/听/找/查 + 有声书名/主播/类型」），走强规则分支；\n- 0：非强规则，走分类模型分支。",
        "enum": ["0", "1"]
      },
      "nlu_state": {
        "type": "string",
        "description": "NLU 多轮交互状态。0-无需多轮；1~3-发生多轮改写；4-需多轮但未改写(会被转为 audio_chat 问答意图)。",
        "enum": ["0", "1", "2", "3", "4"]
      },
      "rewrite_query": {
        "type": "string",
        "description": "多轮改写后的查询文本，用于替代 query 参与下游检索；无改写时可与 query 相同。"
      },
      "audio_version": {
        "type": "string",
        "description": "终端有声APK版本号(取自 configMap.audioversion)。为空表示未安装APK，此时熄屏播放会兜底为亮屏参数；等于 3rd.audio.689 表示不支持历史起播。"
      },
      "biz_type": {
        "type": "string",
        "description": "业务分类标识，用于多tab/子领域区分，如 audio、multitab 等。"
      },
      "config_map": {
        "type": "object",
        "description": "终端上下文透传字段集合，包含 tvmode、audioversion、license、customerId、coreVersion、vodAbility、preServiceData 等，用于下游拼接检索URL和判断熄屏/切换媒资分支。"
      },
      "trace_id": {
        "type": "string",
        "description": "链路追踪ID，用于日志串联和调试。"
      }
    },
    "required": ["query", "play_mode"]
  },
  "output": {
    "type": "object",
    "properties": {
      "data": {
        "type": "object",
        "description": "有声搜索业务数据体",
        "properties": {
          "viewtype": {"type": "string", "description": "终端视图类型，固定为 audiosearchview（有声搜索卡片）"},
          "titledata": {"type": "string", "description": "卡片主标题话术，如润色后的回复语或兜底话术"},
          "content": {
            "type": "object",
            "description": "媒资内容体",
            "properties": {
              "searchResultList": {
                "type": "array",
                "description": "搜索结果分组列表，每组包含 appName、appType、data(媒资项列表：id/typeCode/showInfo.title/aivbInfo.total/jumppara 等)"
              }
            }
          },
          "loginfo": {
            "type": "object",
            "description": "埋点日志，含 appname=audio、agenttype=agent_audio、agentintent=agent_audio_search、apptype=37、sourcetype=搜索、sourcedatatype=普通搜索/兜底搜索 等"
          }
        }
      },
      "llmSemantic": {
        "type": "object",
        "description": "大模型语义回填",
        "properties": {
          "domain": {"type": "string", "description": "领域标识，固定为 AUDIO_TOPIC"},
          "intent": {"type": "string", "description": "最终落地意图值：audio_search / audio_play / audio_screen_off_play 之一"}
        }
      },
      "sort": {"type": "string", "description": "一级分类，audio（有声）或 chatting（无媒资闲聊兜底）"},
      "subsort": {"type": "string", "description": "二级分类：audio(展示列表) / audio_play(直接起播) / chatting(闲聊) / hisapp(直达)"},
      "ttscontent": {"type": "string", "description": "TTS 播报话术，包含亮屏/熄屏差异化模板，可能填充 ${title}、${total}"},
      "screenoper": {"type": "string", "description": "屏幕操作指令：1=亮屏，0=熄屏，仅在熄屏/切换媒资等场景下发"},
      "priority": {"type": "string", "description": "终端优先级处理标识，通常为空串"},
      "memoryData": {
        "type": "array",
        "description": "多轮记忆数据，每项含 sort、subsort、data(id/typeCode/title)，供后续多轮上下文引用"
      }
    },
    "usage_hint": "①根据 subsort 决定终端行为：audio→渲染卡片列表，audio_play→取 searchResultList[0].data[0] 直接起播，chatting→仅播报 ttscontent；②将 ttscontent 交给TTS播报；③按 screenoper 切换亮/熄屏；④memoryData 写入多轮记忆用于「继续听」「下一部」类追问。"
  },
  "error_output": {
    "type": "object",
    "properties": {
      "error_code": {
        "type": "string",
        "description": "错误码。AUDIO_MEDIA_EMPTY-媒资为空；AUDIO_APP_UNSUPPORTED-终端未装有声APK；AUDIO_SEARCH_TIMEOUT-下游有声媒资查询超时；AUDIO_INTENT_INVALID-play_mode 非法。"
      },
      "error_message": {"type": "string", "description": "错误描述"}
    }
  },
  "examples": [
    {
      "scenario": "亮屏搜索：多结果卡片列表",
      "input": {
        "query": "郭德纲的相声",
        "retext": "我想听郭德纲的相声",
        "play_mode": "search",
        "screen_mode": "normal",
        "rule_intent_flag": "1",
        "nlu_state": "0",
        "word_list": [{"word": "郭德纲", "tag": "audioSinger"}, {"word": "相声", "tag": "audioType"}],
        "audio_version": "3rd.audio.700",
        "trace_id": "trace-0001"
      },
      "output": {
        "data": {
          "viewtype": "audiosearchview",
          "titledata": "为您找到郭德纲的相声",
          "content": {"searchResultList": [{"appName": "有声", "appType": "37", "data": [{"id": 10001, "showInfo": {"title": "郭德纲经典相声集"}, "jumppara": "..."}]}]},
          "loginfo": {"appname": "audio", "agentintent": "agent_audio_search", "sourcedatatype": "普通搜索"}
        },
        "llmSemantic": {"domain": "AUDIO_TOPIC", "intent": "audio_search"},
        "sort": "audio",
        "subsort": "audio",
        "ttscontent": "为您找到郭德纲的相声",
        "priority": "",
        "memoryData": [{"sort": "audio", "subsort": "audio", "data": [{"id": 10001, "title": "郭德纲经典相声集"}]}]
      }
    },
    {
      "scenario": "亮屏播放：单一媒资直接起播",
      "input": {
        "query": "三国演义评书",
        "retext": "播放三国演义评书",
        "play_mode": "play",
        "screen_mode": "normal",
        "rule_intent_flag": "1",
        "word_list": [{"word": "三国演义", "tag": "audioName"}, {"word": "评书", "tag": "audioType"}, {"word": "播放", "tag": "control"}]
      },
      "output": {
        "data": {
          "viewtype": "audiosearchview",
          "titledata": "即将为您播放三国演义",
          "content": {"searchResultList": [{"appName": "有声", "appType": "37", "data": [{"id": 20002, "showInfo": {"title": "三国演义"}, "aivbInfo": {"total": "120"}}]}]},
          "loginfo": {"appname": "audio", "agentintent": "agent_audio_search"}
        },
        "llmSemantic": {"domain": "AUDIO_TOPIC", "intent": "audio_play"},
        "sort": "audio",
        "subsort": "audio_play",
        "ttscontent": "即将为您播放三国演义"
      }
    },
    {
      "scenario": "熄屏播放：熄屏参数下发",
      "input": {
        "query": "睡前故事",
        "retext": "熄屏听会儿睡前故事",
        "play_mode": "screen_off_play",
        "screen_mode": "screen_standby",
        "config_map": {"tvmode": "6", "audioversion": "3rd.audio.700"}
      },
      "output": {
        "data": {"viewtype": "audiosearchview", "titledata": "已为您在熄屏播放睡前故事，共30集", "content": {"searchResultList": [{"data": [{"id": 30003, "showInfo": {"title": "睡前故事精选"}, "aivbInfo": {"total": "30"}}]}]}},
        "llmSemantic": {"domain": "AUDIO_TOPIC", "intent": "audio_screen_off_play"},
        "sort": "audio",
        "subsort": "audio_play",
        "ttscontent": "已为您在熄屏播放睡前故事，共30集",
        "screenoper": "0"
      }
    },
    {
      "scenario": "无媒资兜底：闲聊话术",
      "input": {"query": "火星登陆纪实广播剧", "play_mode": "search", "screen_mode": "normal"},
      "output": {
        "data": {"viewtype": "audiosearchview", "titledata": "抱歉没找到相关有声内容", "content": "抱歉没找到相关有声内容"},
        "sort": "chatting",
        "subsort": "chatting",
        "ttscontent": "抱歉没找到相关有声内容"
      }
    },
    {
      "scenario": "熄屏但未装APK：兜底为亮屏",
      "input": {"query": "郭德纲相声", "play_mode": "screen_off_play", "screen_mode": "screen_standby", "config_map": {"tvmode": "6", "audioversion": ""}},
      "output": {
        "sort": "audio",
        "subsort": "audio_play",
        "screenoper": "1",
        "ttscontent": "即将为您播放郭德纲相声",
        "llmSemantic": {"domain": "AUDIO_TOPIC", "intent": "audio_screen_off_play"}
      }
    },
    {
      "scenario": "参数异常",
      "input": {"query": "郭德纲", "play_mode": "invalid_mode"},
      "output": {"error_code": "AUDIO_INTENT_INVALID", "error_message": "play_mode 非法，仅支持 search/play/screen_off_play"}
    }
  ]
}

{
  "name": "audio_chat_qa",
  "title": "有声内容问答",
  "url": "http://{juaiagent-host}:{port}/api/v1.0/agent/stream",
  "method": "POST",
  "description": "功能：基于用户当前正在收听（或多轮指代）的有声内容上下文，调用大语言模型生成流式问答回复。支持三类上下文场景：(1)有在播内容时自动获取专辑标题、主播、当前分集集数作为上下文；(2)有多轮指代实体时直接提取标题与主播作为上下文；(3)无上下文时仅转发用户原始问题。\n适用场景：用户针对有声在播内容或上文提到的有声媒资提问，如「这本书作者是谁」「这个主播还有什么作品」「这本书一共多少集」「现在听的是第几集」「帮我介绍一下这本书」等。\n不适用场景：用户目的是搜索/播放某个有声内容（应使用audio_search）；用户想要打开有声首页/历史记录（应使用audio_page/audio_history）；用户做设备控制如暂停/下一集（应使用设备控制智能体）；用户问通用知识/天气/新闻等与在播有声内容无关的问题（应使用通用问答）。\n关联工具：有声搜索用 audio_search，直达页面用 audio_page，历史记录起播用 audio_history，通用闲聊用 general_chat。\n异常：在播信息获取失败时仅转发用户原始问题（LLM自行判断能否回答）；LLM响应超时或异常时返回兜底结束帧。\n结果使用：将流式文本逐帧拼接后作为TTS播报及文本展示给用户；若结果为finish帧则标志回答结束。",
  "parameters": {
    "type": "object",
    "properties": {
      "query": {
        "type": "string",
        "description": "用户的问题文本（对应 normalText），如「这本书一共多少集」「作者是谁」「帮我介绍一下这个评书」。"
      },
      "entity_info_list": {
        "type": "array",
        "description": "实体信息列表，由上游NLU指代解析下发。每个元素包含 sort(分类,hisapp=有声)、type(类型,CURRENT_PLAYING=在播)、data(媒资列表含id/thirdSongId/title/author)。当 type=CURRENT_PLAYING 时工具会自动调用 itemDetail 接口补全专辑详情和当前分集集数；当 sort=hisapp 且 type≠CURRENT_PLAYING 时直接提取标题与主播作为上下文。"
      },
      "config_map": {
        "type": "object",
        "description": "终端设备上下文参数，主要供查询 itemDetail 接口使用。关键字段：deviceid(设备ID)、hisappversion(应用版本)、license(授权码)、customerid(客户ID)。"
      },
      "word_list": {
        "type": "array",
        "description": "分词与语义标签列表，随 llmSemantic.content 透传给流式问答阶段，用于辅助模型理解用户问句上下文。"
      },
      "intention": {
        "type": "string",
        "description": "当前意图标识，固定传 audio_chat，用于流式接口路由和结果标识。",
        "enum": ["audio_chat"]
      },
      "nlu_state": {
        "type": "string",
        "description": "NLU多轮交互状态。4=需多轮但未改写直接进入问答；0~3=正常交互/已改写。",
        "enum": ["0", "1", "2", "3", "4"]
      },
      "trace_id": {
        "type": "string",
        "description": "链路追踪ID，用于日志串联和调试。"
      }
    },
    "required": ["query", "intention"]
  },
  "output": {
    "type": "object",
    "properties": {
      "phase1_response": {
        "type": "object",
        "description": "第一阶段（非流式handle接口）返回结果，告知调用方需要继续发起流式请求",
        "properties": {
          "llmSemantic": {
            "type": "object",
            "description": "语义信息",
            "properties": {
              "domain": {"type": "string", "description": "领域标识，固定为 AUDIO_TOPIC"},
              "intent": {"type": "string", "description": "意图标识，固定为 audio_chat"},
              "content": {"type": "string", "description": "透传给流式阶段的上下文JSON（含 wordList 分词信息）"},
              "isMultipleCalls": {"type": "boolean", "description": "是否需要多次调用（流式），固定为 true"}
            }
          },
          "sort": {"type": "string", "description": "一级分类，固定为 chatting"},
          "subsort": {"type": "string", "description": "二级分类，固定为 chatting"},
          "ttscontent": {"type": "string", "description": "TTS内容，问答意图下为空字符串（由流式阶段输出）"}
        }
      },
      "phase2_stream_response": {
        "type": "object",
        "description": "第二阶段（流式handleStream接口）逐帧返回结果",
        "properties": {
          "text": {"type": "string", "description": "当前帧的文本增量内容"},
          "seq_number": {"type": "integer", "description": "当前帧序号，从0递增"},
          "finish": {"type": "boolean", "description": "是否为结束帧，true 时表示回答完毕"},
          "intention": {"type": "string", "description": "意图标识，始终为 audio_chat"}
        }
      }
    },
    "usage_hint": "Phase1仅做意图确认(isMultipleCalls=true)，不携带实际回复内容；Phase2为流式文本输出，终端逐帧拼接text字段显示并送入TTS播报，finish=true时停止拼接。若问答结果为空则展示兜底话术。"
  },
  "error_output": {
    "type": "object",
    "properties": {
      "error_code": {"type": "string", "description": "错误码。PARAM_ERROR_TEXT_REQUIRED-normalText为空；PARAM_ERROR_CONFIGMAP_REQUIRED-configMap为空；LLM_CALL_FAILED-大模型调用失败；MEDIA_INFO_FETCH_FAILED-在播信息获取失败(非阻断性,降级为无上下文问答)。"},
      "error_message": {"type": "string", "description": "错误描述信息"}
    }
  },
  "examples": [
    {
      "scenario": "针对在播有声书提问（有CURRENT_PLAYING实体）",
      "input": {
        "query": "这本书一共多少集",
        "intention": "audio_chat",
        "entity_info_list": [
          {
            "sort": "hisapp",
            "type": "CURRENT_PLAYING",
            "data": [{"id": "10001", "thirdSongId": "20001", "title": "三国演义", "author": "袁阔成"}]
          }
        ],
        "config_map": {"deviceid": "device_001", "hisappversion": "3rd.audio.700", "license": "xxx", "customerid": "cust_001"},
        "trace_id": "trace-qa-001"
      },
      "output": {
        "phase1_response": {
          "llmSemantic": {"domain": "AUDIO_TOPIC", "intent": "audio_chat", "content": "{\"wordList\":[...]}", "isMultipleCalls": true},
          "sort": "chatting",
          "subsort": "chatting",
          "ttscontent": ""
        },
        "phase2_stream_response": [
          {"text": "《三国演义》评书由袁阔成播讲，", "seq_number": 0, "finish": false, "intention": "audio_chat"},
          {"text": "一共365集。您当前收听到第128集。", "seq_number": 1, "finish": false, "intention": "audio_chat"},
          {"text": "", "seq_number": 2, "finish": true, "intention": "audio_chat"}
        ]
      }
    },
    {
      "scenario": "多轮指代提问（有非在播指代实体）",
      "input": {
        "query": "这个主播还有什么其他作品",
        "intention": "audio_chat",
        "entity_info_list": [
          {
            "sort": "hisapp",
            "type": "REFERENCE",
            "data": [{"id": "10002", "title": "郭德纲经典相声集", "author": "郭德纲"}]
          }
        ],
        "trace_id": "trace-qa-002"
      },
      "output": {
        "phase1_response": {
